"use client";

import { cn } from "@/lib/utils";
import {
  CanvasStage,
  ImageFallback,
} from "@/registry/ivan/components/canvas-stage/canvas-stage";

import { dustPortraitDefaults } from "./dust-portrait-material";
import { DustPortraitScene } from "./dust-portrait-scene";
import type { DustPortraitSceneProps } from "./dust-portrait-scene";

export interface DustPortraitProps extends Omit<
  DustPortraitSceneProps,
  "pointerTarget"
> {
  alt?: string;
  className?: string;
}

const defaultAlt = "A picture printed in dust that scatters under the pointer";
const centeredFocus = { x: 0.5, y: 0.5 };

export const DustPortrait = ({
  alt = defaultAlt,
  className,
  src,
  focus = centeredFocus,
  ink = dustPortraitDefaults.ink,
  paused = dustPortraitDefaults.paused,
  ...sceneProps
}: DustPortraitProps) => (
  <CanvasStage
    className={cn("touch-pan-y", className)}
    fallback={<ImageFallback focus={focus} src={src} />}
    ground={ink}
    label={alt}
    paused={paused}
  >
    {(isAnimating) => (
      <DustPortraitScene
        {...sceneProps}
        focus={focus}
        ink={ink}
        paused={!isAnimating}
        src={src}
      />
    )}
  </CanvasStage>
);

"use client";

import { useFrame, useThree } from "@react-three/fiber";
import { useEffect, useMemo, useState } from "react";
import type { RefObject } from "react";
import { PlaneGeometry, Vector4 } from "three";
import type { WebGLRenderer } from "three";

import { usePrintImage } from "@/registry/ivan/hooks/use-print-image";

import { DustBursts } from "./dust-portrait-bursts";
import {
  budgetDustCount,
  createDustGeometry,
  resolveDustCount,
  sampleDustField,
} from "./dust-portrait-field";
import type { DustFocus } from "./dust-portrait-field";
import { DustGroundMaterial } from "./dust-portrait-ground";
import {
  DustPortraitMaterial,
  dustPortraitDefaults,
  isLighterThan,
} from "./dust-portrait-material";
import { DustTrail } from "./dust-portrait-trail";

export interface DustPortraitSceneProps {
  src: string;
  burst?: boolean;
  focus?: DustFocus;
  density?: number;
  dispersion?: number;
  drift?: number;
  idle?: boolean | number;
  ink?: string;
  paper?: string;
  paused?: boolean;
  pointerTarget?: RefObject<HTMLElement | null>;
}

interface StageBox {
  width: number;
  height: number;
}

const centeredFocus: DustFocus = { x: 0.5, y: 0.5 };
const maxStep = 0.05;
const revealRate = 7;
const aspectPrecision = 100;
const viewport = new Vector4();

class DustRig {
  readonly trail = new DustTrail();
  readonly bursts = new DustBursts();
  readonly material = new DustPortraitMaterial(
    this.trail.uniform,
    this.bursts.uniform
  );
  readonly ground = new DustGroundMaterial({
    uAspect: this.material.uniforms.uAspect,
    uBursts: this.material.uniforms.uBursts,
    uMark: this.material.uniforms.uMark,
    uTime: this.material.uniforms.uTime,
  });
  readonly groundGeometry = new PlaneGeometry(1, 1);
  private rows = 1;
  private elapsed = 0;
  private reveal = 0;
  private imageElement: HTMLImageElement | null = null;

  applyLook(ink: string, paper: string, dispersion: number, drift: number) {
    const { uniforms } = this.material;
    uniforms.uMark.value.set(paper);
    uniforms.uIsLitMark.value = isLighterThan(paper, ink) ? 1 : 0;
    uniforms.uDispersion.value = dispersion;
    uniforms.uDrift.value = drift;
    this.ground.uniforms.uGround.value.set(ink);
  }

  adoptField(rows: number, imageElement: HTMLImageElement) {
    this.rows = rows;
    if (imageElement !== this.imageElement) {
      this.imageElement = imageElement;
      this.reveal = 0;
      this.writeReveal();
    }
  }

  burst(x: number, y: number) {
    this.bursts.add(x, y, this.elapsed);
  }

  readonly handleBeforeRender = (renderer: WebGLRenderer) => {
    renderer.getCurrentViewport(viewport);
    const { uniforms } = this.material;
    uniforms.uAspect.value = viewport.z / Math.max(viewport.w, 1);
    uniforms.uCellPx.value = viewport.w / Math.max(this.rows, 1);
  };

  advance(delta: number, paused: boolean, idle: number) {
    const step = Math.min(delta, maxStep);
    const { uniforms } = this.material;
    if (paused) {
      this.trail.clear();
      this.bursts.clear();
      this.reveal = 1;
      uniforms.uIdle.value = 0;
      this.writeReveal();
      return false;
    }
    this.trail.advance(step);
    this.elapsed += step;
    this.reveal += (1 - this.reveal) * (1 - Math.exp(-revealRate * step));
    if (this.reveal > 0.995) {
      this.reveal = 1;
    }
    uniforms.uTime.value = this.elapsed;
    uniforms.uIdle.value = idle;
    this.writeReveal();
    return (
      idle > 0 ||
      !this.trail.isSettled ||
      this.bursts.isActiveAt(this.elapsed) ||
      this.reveal < 1
    );
  }

  dispose() {
    this.material.dispose();
    this.ground.dispose();
    this.groundGeometry.dispose();
  }

  private writeReveal() {
    this.material.uniforms.uReveal.value = this.reveal;
    this.ground.uniforms.uReveal.value = this.reveal;
  }
}

const resolveTarget = (
  pointerTarget: RefObject<HTMLElement | null> | undefined,
  canvas: HTMLElement
) => pointerTarget?.current ?? canvas;

const useStageBox = (
  pointerTarget: RefObject<HTMLElement | null> | undefined,
  canvas: HTMLElement
) => {
  const [box, setBox] = useState<StageBox | null>(null);

  useEffect(() => {
    const target = resolveTarget(pointerTarget, canvas);
    if (!target) {
      return;
    }
    const observer = new ResizeObserver(([entry]) => {
      if (!entry) {
        return;
      }
      const { width, height } = entry.contentRect;
      if (width > 0 && height > 0) {
        setBox((current) =>
          current?.width === width && current.height === height
            ? current
            : { height, width }
        );
      }
    });
    observer.observe(target);
    return () => observer.disconnect();
  }, [canvas, pointerTarget]);

  return box;
};

interface PointerTrailInput {
  pointerTarget: RefObject<HTMLElement | null> | undefined;
  canvas: HTMLElement;
  trail: DustTrail;
  isEnabled: boolean;
  invalidate: () => void;
}

const usePointerTrail = ({
  pointerTarget,
  canvas,
  trail,
  isEnabled,
  invalidate,
}: PointerTrailInput) => {
  useEffect(() => {
    const target = resolveTarget(pointerTarget, canvas);
    if (!(target && isEnabled)) {
      return;
    }
    const aim = (event: PointerEvent) => {
      const rect = target.getBoundingClientRect();
      trail.aim(
        (event.clientX - rect.left) / Math.max(rect.width, 1),
        1 - (event.clientY - rect.top) / Math.max(rect.height, 1)
      );
      invalidate();
    };
    const release = () => {
      trail.release();
      invalidate();
    };
    const lift = (event: PointerEvent) => {
      if (event.pointerType !== "mouse") {
        release();
      }
    };
    target.addEventListener("pointermove", aim);
    target.addEventListener("pointerdown", aim);
    target.addEventListener("pointerleave", release);
    target.addEventListener("pointercancel", release);
    target.addEventListener("pointerup", lift);
    return () => {
      target.removeEventListener("pointermove", aim);
      target.removeEventListener("pointerdown", aim);
      target.removeEventListener("pointerleave", release);
      target.removeEventListener("pointercancel", release);
      target.removeEventListener("pointerup", lift);
      trail.release();
    };
  }, [canvas, invalidate, isEnabled, pointerTarget, trail]);
};

interface BurstClickInput {
  pointerTarget: RefObject<HTMLElement | null> | undefined;
  canvas: HTMLElement;
  rig: DustRig;
  isEnabled: boolean;
  invalidate: () => void;
}

const useBurstClick = ({
  pointerTarget,
  canvas,
  rig,
  isEnabled,
  invalidate,
}: BurstClickInput) => {
  useEffect(() => {
    const target = resolveTarget(pointerTarget, canvas);
    if (!(target && isEnabled)) {
      return;
    }
    const strike = (event: MouseEvent) => {
      const rect = target.getBoundingClientRect();
      rig.burst(
        (event.clientX - rect.left) / Math.max(rect.width, 1),
        1 - (event.clientY - rect.top) / Math.max(rect.height, 1)
      );
      invalidate();
    };
    target.addEventListener("click", strike);
    return () => target.removeEventListener("click", strike);
  }, [canvas, invalidate, isEnabled, pointerTarget, rig]);
};

export const DustPortraitScene = ({
  src,
  burst = dustPortraitDefaults.burst,
  focus = centeredFocus,
  density = dustPortraitDefaults.density,
  dispersion = dustPortraitDefaults.dispersion,
  drift = dustPortraitDefaults.drift,
  idle = dustPortraitDefaults.idle,
  ink = dustPortraitDefaults.ink,
  paper = dustPortraitDefaults.paper,
  paused = dustPortraitDefaults.paused,
  pointerTarget,
}: DustPortraitSceneProps) => {
  const invalidate = useThree((state) => state.invalidate);
  const canvas = useThree((state) => state.gl.domElement);
  const rig = useMemo(() => new DustRig(), []);
  const image = usePrintImage(src);
  const box = useStageBox(pointerTarget, canvas);
  const deviceCount = useMemo(() => resolveDustCount(), []);
  const isLitMark = isLighterThan(paper, ink);
  const idleStrength = Math.max(0, Number(idle));

  usePointerTrail({
    canvas,
    invalidate,
    isEnabled: !paused,
    pointerTarget,
    trail: rig.trail,
  });

  useBurstClick({
    canvas,
    invalidate,
    isEnabled: burst && !paused,
    pointerTarget,
    rig,
  });

  useEffect(() => () => rig.dispose(), [rig]);

  useEffect(() => {
    rig.applyLook(ink, paper, dispersion, drift);
    invalidate();
  }, [dispersion, drift, ink, invalidate, paper, rig]);

  const aspect = box
    ? Math.round((box.width / box.height) * aspectPrecision) / aspectPrecision
    : null;
  const count = box
    ? budgetDustCount(deviceCount, density, box.width, box.height)
    : 0;
  const roundedCount = Math.round(count / 1000) * 1000;

  const field = useMemo(() => {
    if (!(image && aspect)) {
      return null;
    }
    return sampleDustField({
      aspect,
      count: roundedCount,
      focus: { x: focus.x, y: focus.y },
      image: image.element,
      isLitMark,
    });
  }, [aspect, focus.x, focus.y, image, isLitMark, roundedCount]);

  const geometry = useMemo(
    () => (field ? createDustGeometry(field) : null),
    [field]
  );

  useEffect(() => {
    if (!geometry) {
      return;
    }
    return () => geometry.dispose();
  }, [geometry]);

  useEffect(() => {
    if (!(field && image)) {
      return;
    }
    rig.adoptField(field.rows, image.element);
    invalidate();
  }, [field, image, invalidate, rig]);

  useFrame((_, delta) => {
    if (!geometry) {
      return;
    }
    if (rig.advance(delta, paused, idleStrength)) {
      invalidate();
    }
  });

  if (!geometry) {
    return null;
  }

  return (
    <>
      <mesh
        frustumCulled={false}
        geometry={rig.groundGeometry}
        material={rig.ground}
        renderOrder={0}
      />
      <points
        frustumCulled={false}
        geometry={geometry}
        material={rig.material}
        onBeforeRender={rig.handleBeforeRender}
        renderOrder={1}
      />
    </>
  );
};

import { Color, NormalBlending, ShaderMaterial } from "three";
import type { IUniform, Vector3 } from "three";

import { dustBurstChunk } from "./dust-portrait-bursts";
import { dustTrailLength } from "./dust-portrait-trail";

export const dustPortraitDefaults = {
  burst: true,
  density: 1,
  dispersion: 1,
  drift: 1,
  idle: true,
  ink: "#0B0B0C",
  paper: "#EDECE8",
  paused: false,
} as const;

export interface DustPortraitUniforms {
  [uniform: string]: IUniform;
  uAspect: IUniform<number>;
  uBursts: IUniform<Vector3[]>;
  uCellPx: IUniform<number>;
  uDispersion: IUniform<number>;
  uDrift: IUniform<number>;
  uIdle: IUniform<number>;
  uMark: IUniform<Color>;
  uIsLitMark: IUniform<number>;
  uRadius: IUniform<number>;
  uReveal: IUniform<number>;
  uTime: IUniform<number>;
  uTrail: IUniform<Vector3[]>;
}

const noiseChunk = `
  vec3 permute3(vec3 x) {
    return mod(((x * 34.0) + 1.0) * x, 289.0);
  }

  float simplex(vec2 v) {
    const vec4 C = vec4(0.211324865405187, 0.366025403784439, -0.577350269189626, 0.024390243902439);
    vec2 i = floor(v + dot(v, C.yy));
    vec2 x0 = v - i + dot(i, C.xx);
    vec2 i1 = x0.x > x0.y ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
    vec4 x12 = x0.xyxy + C.xxzz;
    x12.xy -= i1;
    i = mod(i, 289.0);
    vec3 p = permute3(permute3(i.y + vec3(0.0, i1.y, 1.0)) + i.x + vec3(0.0, i1.x, 1.0));
    vec3 m = max(0.5 - vec3(dot(x0, x0), dot(x12.xy, x12.xy), dot(x12.zw, x12.zw)), 0.0);
    m = m * m;
    m = m * m;
    vec3 x = 2.0 * fract(p * C.www) - 1.0;
    vec3 h = abs(x) - 0.5;
    vec3 ox = floor(x + 0.5);
    vec3 a0 = x - ox;
    m *= 1.79284291400159 - 0.85373472095314 * (a0 * a0 + h * h);
    vec3 g;
    g.x = a0.x * x0.x + h.x * x0.y;
    g.yz = a0.yz * x12.xz + h.yz * x12.yw;
    return 130.0 * dot(m, g);
  }

  vec2 curl(vec2 p) {
    const float e = 0.08;
    float up = simplex(p + vec2(0.0, e));
    float down = simplex(p - vec2(0.0, e));
    float right = simplex(p + vec2(e, 0.0));
    float left = simplex(p - vec2(e, 0.0));
    return vec2(up - down, left - right) / (2.0 * e);
  }
`;

const vertexShader = `
  #define TRAIL ${dustTrailLength + 1}

  attribute vec2 aMeta;

  uniform vec3 uTrail[TRAIL];
  uniform float uAspect;
  uniform float uRadius;
  uniform float uDispersion;
  uniform float uDrift;
  uniform float uTime;
  uniform float uIdle;
  uniform float uCellPx;
  uniform float uIsLitMark;
  uniform float uReveal;

  varying float vAlpha;
  varying float vRadius;
  varying float vSize;

  ${noiseChunk}
  ${dustBurstChunk}

  struct BurstPush {
    vec2 offset;
    float amount;
    float ring;
  };

  BurstPush burstPushAt(vec2 stageHome, float seed) {
    BurstPush push = BurstPush(vec2(0.0), 0.0, 0.0);
    vec2 swirl = vec2(0.0);
    bool hasSwirl = false;
    float rise = BURST_RISE * (0.75 + 0.5 * fract(seed * 5.71));
    float reach = 0.1 + 0.08 * fract(seed * 9.13);
    for (int index = 0; index < BURSTS; index++) {
      vec3 burst = uBursts[index];
      float age = uTime - burst.z;
      if (age < 0.0 || age > BURST_SECONDS) {
        continue;
      }
      vec2 delta = stageHome - burst.xy * vec2(uAspect, 1.0);
      float gap = length(delta);
      float local = (age - burstArrival(gap)) / rise;
      if (local <= 0.0) {
        continue;
      }
      if (!hasSwirl) {
        swirl = curl(stageHome * 3.1 + seed * 0.3);
        hasSwirl = true;
      }
      float response = local * exp(1.0 - local);
      float falloff = exp(-gap * 3.2);
      float angle = seed * 6.2832;
      vec2 radial = gap > 0.0001 ? delta / gap : vec2(cos(angle), sin(angle));
      vec2 direction = normalize(radial + swirl * 0.45 * uDispersion + vec2(uDrift * 0.15, 0.0));
      push.offset += direction * response * falloff * reach;
      push.amount = max(push.amount, response * falloff);
      float fade = 1.0 - smoothstep(0.0, BURST_WAVE_SECONDS * 1.3, age);
      push.ring = max(push.ring, exp(-pow((local - 0.7) * 1.8, 2.0)) * fade);
    }
    float travel = length(push.offset);
    if (travel > 0.28) {
      push.offset *= 0.28 / travel;
    }
    push.amount = min(push.amount, 1.0);
    return push;
  }

  float influenceAt(vec2 home, float ragged) {
    float strongest = 0.0;
    vec2 scale = vec2(uAspect, 1.0);
    for (int index = 0; index < TRAIL; index++) {
      vec3 mark = uTrail[index];
      if (mark.z < 0.001) {
        continue;
      }
      vec2 delta = (home - mark.xy) * scale;
      delta.x *= delta.x > 0.0 ? 0.62 : 1.2;
      float reach = length(delta) / (uRadius * ragged);
      strongest = max(strongest, mark.z * (1.0 - smoothstep(0.3, 1.0, reach)));
    }
    return strongest;
  }

  void main() {
    vec2 home = position.xy;
    float luma = position.z;
    float seed = aMeta.x;
    float edge = aMeta.y;
    vec2 stageHome = home * vec2(uAspect, 1.0);

    float ragged = 0.78 + 0.44 * (simplex(stageHome * 9.0) * 0.5 + 0.5);
    float pushed = influenceAt(home, ragged);
    float idle = min(uIdle, 3.0);
    float windward = smoothstep(0.45, 1.0, home.x);
    float shedRate = 0.975 - idle * (0.012 + windward * 0.07);
    float shedder = step(shedRate, fract(seed * 7.31)) * step(0.22 * (1.0 - windward * min(idle, 1.0)), edge);
    float shed = min(idle, 1.0) * shedder * pow(max(sin(uTime * (0.22 + 0.3 * seed) + seed * 43.0), 0.0), mix(10.0, 4.0, windward * min(idle, 1.0))) * (0.55 + 0.25 * windward);
    float gustFront = fract(uTime * 0.045 + seed * 0.015);
    float gustBand = exp(-pow((home.x - (gustFront * 1.6 - 0.3)) * 7.0, 2.0));
    float gustLift = step(0.82, fract(seed * 5.13 + floor(uTime * 0.045) * 0.37));
    float gust = min(idle, 2.0) * 0.18 * gustBand * gustLift * (0.35 + 0.65 * windward);
    float amount = max(max(pushed, shed), gust);
    amount = amount * amount * (3.0 - 2.0 * amount);

    vec2 offset = vec2(0.0);
    if (amount > 0.0005) {
      float lag = 0.35 + 0.65 * fract(seed * 3.17);
      vec2 flow = curl(stageHome * 2.4 + vec2(-uTime * 0.16, uTime * 0.05) + seed * 0.4);
      float gust = 0.85 + 0.15 * sin(uTime * 0.9 + seed * 20.0);
      offset = flow * uDispersion * 0.09 * lag;
      offset += vec2(uDrift * 0.42 * lag * gust, (seed - 0.45) * 0.06 * uDispersion);
      offset *= amount;
    }

    BurstPush burst = burstPushAt(stageHome, seed);
    offset += burst.offset;
    offset += idle * windward * windward * 0.0016 * vec2(sin(uTime * 1.3 + seed * 50.0), cos(uTime * 1.1 + seed * 31.0));
    vec2 stage = home + vec2(offset.x / uAspect, offset.y);
    gl_Position = vec4(stage * 2.0 - 1.0, 0.0, 1.0);

    float coverage = mix(1.0 - luma, luma, uIsLitMark);
    float scatter = max(amount, burst.amount * 0.8);
    float grain = mix(1.0, 0.62 + 0.28 * seed, scatter);
    vRadius = sqrt(coverage) * 0.64 * uCellPx * grain * (1.0 + 0.45 * burst.ring);
    vSize = ceil(uCellPx * 1.35 + 2.0);
    vAlpha = min(mix(1.0, 0.5 + 0.5 * fract(seed * 13.7), scatter) + burst.ring * 0.5, 1.0) * uReveal;
    gl_PointSize = vSize;
  }
`;

const fragmentShader = `
  uniform vec3 uMark;

  varying float vAlpha;
  varying float vRadius;
  varying float vSize;

  void main() {
    float reach = length(gl_PointCoord - 0.5) * vSize;
    float alpha = (1.0 - smoothstep(vRadius - 0.6, vRadius + 0.6, reach)) * vAlpha;
    if (alpha < 0.004) {
      discard;
    }
    gl_FragColor = vec4(uMark, alpha);
    #include <colorspace_fragment>
  }
`;

export const createDustUniforms = (
  trail: Vector3[],
  bursts: Vector3[]
): DustPortraitUniforms => ({
  uAspect: { value: 1 },
  uBursts: { value: bursts },
  uCellPx: { value: 2 },
  uDispersion: { value: dustPortraitDefaults.dispersion },
  uDrift: { value: dustPortraitDefaults.drift },
  uIdle: { value: 0 },
  uIsLitMark: { value: 1 },
  uMark: { value: new Color(dustPortraitDefaults.paper) },
  uRadius: { value: 0.16 },
  uReveal: { value: 0 },
  uTime: { value: 0 },
  uTrail: { value: trail },
});

export class DustPortraitMaterial extends ShaderMaterial {
  declare uniforms: DustPortraitUniforms;

  constructor(trail: Vector3[], bursts: Vector3[]) {
    super({
      blending: NormalBlending,
      depthTest: false,
      depthWrite: false,
      fragmentShader,
      toneMapped: false,
      transparent: true,
      uniforms: createDustUniforms(trail, bursts),
      vertexShader,
    });
  }
}

const luminance = (value: string) => {
  const { r, g, b } = new Color(value);
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
};

export const isLighterThan = (mark: string, ground: string) =>
  luminance(mark) >= luminance(ground);

import { Color, ShaderMaterial } from "three";
import type { IUniform, Vector3 } from "three";

import { dustBurstChunk } from "./dust-portrait-bursts";

const groundVertexShader = `
  varying vec2 vUv;

  void main() {
    vUv = position.xy + 0.5;
    gl_Position = vec4(position.xy * 2.0, 0.0, 1.0);
  }
`;

const groundFragmentShader = `
  uniform vec3 uGround;
  uniform vec3 uMark;
  uniform float uReveal;
  uniform float uAspect;
  uniform float uTime;

  varying vec2 vUv;

  ${dustBurstChunk}

  void main() {
    vec2 stage = vUv * vec2(uAspect, 1.0);
    float glow = 0.0;
    for (int index = 0; index < BURSTS; index++) {
      vec3 burst = uBursts[index];
      float age = uTime - burst.z;
      if (age < 0.0 || age > BURST_SECONDS) {
        continue;
      }
      float gap = length(stage - burst.xy * vec2(uAspect, 1.0));
      float wave = clamp(age / BURST_WAVE_SECONDS, 0.0, 1.0);
      float ring = exp(-pow((gap - burstFront(age)) / 0.03, 2.0)) * pow(1.0 - wave, 2.0);
      float flash = exp(-age * 12.0) * exp(-pow(gap / 0.14, 2.0));
      glow += 0.2 * ring + 0.32 * flash;
    }
    gl_FragColor = vec4(mix(uGround, uMark, min(glow, 0.5)), uReveal);
    #include <colorspace_fragment>
  }
`;

export interface DustGroundShared {
  uAspect: IUniform<number>;
  uBursts: IUniform<Vector3[]>;
  uMark: IUniform<Color>;
  uTime: IUniform<number>;
}

interface DustGroundUniforms extends DustGroundShared {
  [uniform: string]: IUniform;
  uGround: IUniform<Color>;
  uReveal: IUniform<number>;
}

export class DustGroundMaterial extends ShaderMaterial {
  declare uniforms: DustGroundUniforms;

  constructor(shared: DustGroundShared) {
    super({
      depthTest: false,
      depthWrite: false,
      fragmentShader: groundFragmentShader,
      toneMapped: false,
      transparent: true,
      uniforms: {
        ...shared,
        uGround: { value: new Color("#0B0B0C") },
        uReveal: { value: 0 },
      },
      vertexShader: groundVertexShader,
    });
  }
}

import { BufferAttribute, BufferGeometry } from "three";

export interface DustFocus {
  x: number;
  y: number;
}

export interface DustGrid {
  cols: number;
  rows: number;
}

export interface DustCrop {
  sx: number;
  sy: number;
  sw: number;
  sh: number;
}

export interface DustField {
  count: number;
  rows: number;
  positions: Float32Array;
  meta: Float32Array;
}

export const dustLimits = {
  maxCount: 160_000,
  minCellCss: 1.6,
  minCount: 8000,
} as const;

const lumaWeights = [0.2126, 0.7152, 0.0722] as const;
const hiddenCoverage = 0.035;

export const resolveDustCount = () => {
  if (typeof window === "undefined") {
    return 90_000;
  }
  const isCoarse = window.matchMedia("(pointer: coarse)").matches;
  const cores = navigator.hardwareConcurrency || 4;
  if (isCoarse || cores <= 4) {
    return 45_000;
  }
  return cores >= 10 ? 120_000 : 90_000;
};

export const budgetDustCount = (
  deviceCount: number,
  density: number,
  cssWidth: number,
  cssHeight: number
) => {
  const areaCap =
    (Math.max(cssWidth, 1) * Math.max(cssHeight, 1)) /
    dustLimits.minCellCss ** 2;
  const wanted = Math.min(deviceCount * Math.max(density, 0), areaCap);
  return Math.round(
    Math.min(Math.max(wanted, dustLimits.minCount), dustLimits.maxCount)
  );
};

export const planDustGrid = (count: number, aspect: number): DustGrid => {
  const safeAspect = Math.max(aspect, 0.01);
  const cols = Math.max(2, Math.round(Math.sqrt(count * safeAspect)));
  const rows = Math.max(2, Math.round(cols / safeAspect));
  return { cols, rows };
};

export const coverCrop = (
  imageWidth: number,
  imageHeight: number,
  aspect: number,
  focus: DustFocus
): DustCrop => {
  const imageAspect = imageWidth / imageHeight;
  const sw = aspect > imageAspect ? imageWidth : imageHeight * aspect;
  const sh = aspect > imageAspect ? imageWidth / aspect : imageHeight;
  const sx = Math.min(
    Math.max(focus.x * imageWidth - sw / 2, 0),
    imageWidth - sw
  );
  const sy = Math.min(
    Math.max(focus.y * imageHeight - sh / 2, 0),
    imageHeight - sh
  );
  return { sh, sw, sx, sy };
};

const seedAt = (index: number) => {
  const value = Math.sin(index * 12.9898 + 78.233) * 43_758.5453;
  return value - Math.floor(value);
};

export const buildDustField = (
  pixels: Uint8ClampedArray,
  { cols, rows }: DustGrid,
  isLitMark: boolean
): DustField => {
  const lumas = new Float32Array(cols * rows);
  for (let index = 0; index < cols * rows; index += 1) {
    const offset = index * 4;
    const alpha = (pixels[offset + 3] ?? 255) / 255;
    const luma =
      ((pixels[offset] ?? 0) * lumaWeights[0] +
        (pixels[offset + 1] ?? 0) * lumaWeights[1] +
        (pixels[offset + 2] ?? 0) * lumaWeights[2]) /
      255;
    lumas[index] = isLitMark ? luma * alpha : 1 - (1 - luma) * alpha;
  }
  const lumaAt = (x: number, y: number) =>
    lumas[
      Math.min(Math.max(y, 0), rows - 1) * cols +
        Math.min(Math.max(x, 0), cols - 1)
    ] ?? 0;

  const positions = new Float32Array(cols * rows * 3);
  const meta = new Float32Array(cols * rows * 2);
  let count = 0;
  for (let y = 0; y < rows; y += 1) {
    for (let x = 0; x < cols; x += 1) {
      const luma = lumaAt(x, y);
      const coverage = isLitMark ? luma : 1 - luma;
      if (coverage < hiddenCoverage) {
        continue;
      }
      const neighbors =
        (lumaAt(x - 1, y) +
          lumaAt(x + 1, y) +
          lumaAt(x, y - 1) +
          lumaAt(x, y + 1)) /
        4;
      positions[count * 3] = (x + 0.5) / cols;
      positions[count * 3 + 1] = 1 - (y + 0.5) / rows;
      positions[count * 3 + 2] = luma;
      meta[count * 2] = seedAt(y * cols + x);
      meta[count * 2 + 1] = Math.min(Math.abs(luma - neighbors) * 4, 1);
      count += 1;
    }
  }
  return {
    count,
    meta: meta.slice(0, count * 2),
    positions: positions.slice(0, count * 3),
    rows,
  };
};

export interface DustSampleRequest {
  image: HTMLImageElement;
  aspect: number;
  count: number;
  focus: DustFocus;
  isLitMark: boolean;
}

export const sampleDustField = ({
  image,
  aspect,
  count,
  focus,
  isLitMark,
}: DustSampleRequest): DustField | null => {
  const grid = planDustGrid(count, aspect);
  const canvas = document.createElement("canvas");
  canvas.width = grid.cols;
  canvas.height = grid.rows;
  const context = canvas.getContext("2d", { willReadFrequently: true });
  if (!context) {
    return null;
  }
  const crop = coverCrop(
    image.naturalWidth,
    image.naturalHeight,
    aspect,
    focus
  );
  context.imageSmoothingEnabled = true;
  context.imageSmoothingQuality = "high";
  context.drawImage(
    image,
    crop.sx,
    crop.sy,
    crop.sw,
    crop.sh,
    0,
    0,
    grid.cols,
    grid.rows
  );
  try {
    const { data } = context.getImageData(0, 0, grid.cols, grid.rows);
    return buildDustField(data, grid, isLitMark);
  } catch {
    return null;
  }
};

export const createDustGeometry = (field: DustField) => {
  const geometry = new BufferGeometry();
  geometry.setAttribute("position", new BufferAttribute(field.positions, 3));
  geometry.setAttribute("aMeta", new BufferAttribute(field.meta, 2));
  return geometry;
};

import { Vector3 } from "three";

import { createSpring, driveSpring } from "@/registry/ivan/lib/spring";
import type { Spring, SpringConfig } from "@/registry/ivan/lib/spring";

export const dustTrailLength = 10;

const attack: SpringConfig = { damping: 36, stiffness: 324 };
const release: SpringConfig = { damping: 15, stiffness: 56.25 };
const dropEvery = 0.045;
const dropDistance = 0.012;
const restValue = 0.004;
const restVelocity = 0.02;
const substep = 1 / 120;

interface TrailMark {
  x: number;
  y: number;
  spring: Spring;
}

const createMark = (): TrailMark => ({ spring: createSpring(0), x: 0, y: 0 });

const isResting = ({ value, velocity }: Spring) =>
  Math.abs(value) < restValue && Math.abs(velocity) < restVelocity;

export class DustTrail {
  readonly uniform = Array.from(
    { length: dustTrailLength + 1 },
    () => new Vector3()
  );
  private readonly head = createMark();
  private readonly marks = Array.from({ length: dustTrailLength }, createMark);
  private isPointerIn = false;
  private sinceDrop = 0;
  private nextMark = 0;
  private lastDropX = Number.NaN;
  private lastDropY = Number.NaN;

  aim(x: number, y: number) {
    this.head.x = x;
    this.head.y = y;
    this.isPointerIn = true;
  }

  release() {
    this.isPointerIn = false;
  }

  get isSettled() {
    return (
      !this.isPointerIn &&
      isResting(this.head.spring) &&
      this.marks.every((mark) => isResting(mark.spring))
    );
  }

  get strength() {
    return this.head.spring.value;
  }

  clear() {
    this.isPointerIn = false;
    for (const mark of [this.head, ...this.marks]) {
      mark.spring.value = 0;
      mark.spring.velocity = 0;
    }
    this.write();
  }

  advance(step: number) {
    const { head } = this;
    for (let elapsed = 0; elapsed < step; elapsed += substep) {
      const slice = Math.min(substep, step - elapsed);
      driveSpring(
        head.spring,
        this.isPointerIn ? 1 : 0,
        this.isPointerIn ? attack : release,
        slice,
        true
      );
      for (const mark of this.marks) {
        driveSpring(mark.spring, 0, release, slice, true);
      }
    }
    this.sinceDrop += step;
    const moved =
      Number.isNaN(this.lastDropX) ||
      Math.hypot(head.x - this.lastDropX, head.y - this.lastDropY) >
        dropDistance;
    if (this.isPointerIn && moved && this.sinceDrop >= dropEvery) {
      this.drop();
    }
    for (const mark of [head, ...this.marks]) {
      if (isResting(mark.spring)) {
        mark.spring.value = 0;
        mark.spring.velocity = 0;
      }
    }
    this.write();
  }

  private drop() {
    const { head } = this;
    const mark = this.marks[this.nextMark];
    if (!mark) {
      return;
    }
    mark.x = head.x;
    mark.y = head.y;
    mark.spring.value = Math.max(head.spring.value, mark.spring.value * 0.5);
    mark.spring.velocity = 0;
    this.nextMark = (this.nextMark + 1) % this.marks.length;
    this.sinceDrop = 0;
    this.lastDropX = head.x;
    this.lastDropY = head.y;
  }

  private write() {
    const { head } = this;
    this.uniform[0]?.set(head.x, head.y, Math.max(head.spring.value, 0));
    for (const [index, mark] of this.marks.entries()) {
      this.uniform[index + 1]?.set(
        mark.x,
        mark.y,
        Math.max(mark.spring.value, 0)
      );
    }
  }
}

import { Vector3 } from "three";

export const dustBurstCapacity = 8;

export const dustBurstTiming = {
  reach: 1.15,
  rise: 0.13,
  seconds: 2.4,
  wave: 0.9,
} as const;

const unbornAt = -1e4;

export const dustBurstChunk = `
  #define BURSTS ${dustBurstCapacity}
  #define BURST_REACH ${dustBurstTiming.reach.toFixed(3)}
  #define BURST_RISE ${dustBurstTiming.rise.toFixed(3)}
  #define BURST_SECONDS ${dustBurstTiming.seconds.toFixed(3)}
  #define BURST_WAVE_SECONDS ${dustBurstTiming.wave.toFixed(3)}

  uniform vec3 uBursts[BURSTS];

  float burstFront(float age) {
    float wave = clamp(age / BURST_WAVE_SECONDS, 0.0, 1.0);
    return BURST_REACH * (1.0 - pow(1.0 - wave, 3.0));
  }

  float burstArrival(float gap) {
    float travelled = clamp(gap / BURST_REACH, 0.0, 1.0);
    return BURST_WAVE_SECONDS * (1.0 - pow(1.0 - travelled, 1.0 / 3.0));
  }
`;

export class DustBursts {
  readonly uniform = Array.from(
    { length: dustBurstCapacity },
    () => new Vector3(0, 0, unbornAt)
  );
  private next = 0;
  private lastBirth = unbornAt;

  add(x: number, y: number, birth: number) {
    this.uniform[this.next]?.set(x, y, birth);
    this.next = (this.next + 1) % dustBurstCapacity;
    this.lastBirth = birth;
  }

  isActiveAt(time: number) {
    return time - this.lastBirth < dustBurstTiming.seconds;
  }

  clear() {
    for (const burst of this.uniform) {
      burst.z = unbornAt;
    }
    this.next = 0;
    this.lastBirth = unbornAt;
  }
}

