const reducedMotionQuery = "(prefers-reduced-motion: reduce)";

const subscribe = (onChange: () => void) => {
  const mediaQuery = window.matchMedia(reducedMotionQuery);
  mediaQuery.addEventListener("change", onChange);
  return () => mediaQuery.removeEventListener("change", onChange);
};

const getSnapshot = () => window.matchMedia(reducedMotionQuery).matches;

const getServerSnapshot = () => false;

export const usePrefersReducedMotion = () =>
  useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);

"use client";

import { useSyncExternalStore } from "react";

let cachedSupport: boolean | null = null;

const detectWebGL = () => {
  if (cachedSupport !== null) {
    return cachedSupport;
  }
  try {
    const probe = document.createElement("canvas");
    const context = probe.getContext("webgl2") ?? probe.getContext("webgl");
    context?.getExtension("WEBGL_lose_context")?.loseContext();
    cachedSupport = context !== null;
  } catch {
    cachedSupport = false;
  }
  return cachedSupport;
};

const subscribe = (onChange: () => void) => {
  window.addEventListener("pageshow", onChange);
  return () => window.removeEventListener("pageshow", onChange);
};

const getServerSnapshot = () => true;

export const useWebGLSupport = () =>
  useSyncExternalStore(subscribe, detectWebGL, getServerSnapshot);

"use client";

import { useEffect, useState } from "react";
import type { RefObject } from "react";

export const useInView = (
  target: RefObject<Element | null>,
  rootMargin = "10% 0px"
) => {
  const [isInView, setIsInView] = useState(false);

  useEffect(() => {
    const element = target.current;
    if (!element) {
      return;
    }
    const observer = new IntersectionObserver(
      ([entry]) => setIsInView(entry?.isIntersecting ?? false),
      { rootMargin }
    );
    observer.observe(element);
    return () => observer.disconnect();
  }, [rootMargin, target]);

  return isInView;
};

"use client";

import { useThree } from "@react-three/fiber";
import { useEffect, useState } from "react";
import { LinearMipmapLinearFilter, TextureLoader } from "three";
import type { Texture } from "three";

export interface PrintImage {
  texture: Texture;
  element: HTMLImageElement;
  width: number;
  height: number;
}

interface LoadedImage {
  src: string;
  image: PrintImage;
}

const loadTexture = async (src: string) => {
  const loader = new TextureLoader();
  loader.setCrossOrigin("anonymous");
  try {
    return await loader.loadAsync(src);
  } catch {
    return null;
  }
};

export const usePrintImage = (src: string): PrintImage | null => {
  const invalidate = useThree((state) => state.invalidate);
  const [loaded, setLoaded] = useState<LoadedImage | null>(null);

  useEffect(() => {
    let isCurrent = true;
    let texture: Texture | null = null;
    const load = async () => {
      const value = await loadTexture(src);
      if (!value) {
        return;
      }
      if (!isCurrent) {
        value.dispose();
        return;
      }
      value.generateMipmaps = true;
      value.minFilter = LinearMipmapLinearFilter;
      texture = value;
      const element: HTMLImageElement = value.image;
      setLoaded({
        image: {
          element,
          height: element.naturalHeight,
          texture: value,
          width: element.naturalWidth,
        },
        src,
      });
      invalidate();
    };
    void load();
    return () => {
      isCurrent = false;
      texture?.dispose();
    };
  }, [invalidate, src]);

  return loaded && loaded.src === src ? loaded.image : null;
};
